@Component("termination-handler")
@ProcessingGroup("termination-processing-group")
public class TerminationEventHandler {
	
	// core constructor
	TerminationEventHandler(EntityManager entityManager) {
        this.entityManager = entityManager;
    }	
	
    /*
     * @param	event CreateTerminationEvent
     */
    @EventHandler
    public void handle( CreateTerminationEvent event) {
        entityManager.persist(new Termination(event.getTerminationId(), event.getTerminationNumber(), event.getTerminationDate(), event.getNotes(), event.getEligibleForRehire(), event.getEmployee(), event.getAssignment(), event.getReason(), event.getType()));
    }

    /*
     * @param	event UpdateTerminationEvent
     */
    @EventHandler
    public Termination handle( UpdateTerminationEvent event) {
    	entityManager.merge(new Termination(event.getTerminationId(), event.getTerminationNumber(), event.getTerminationDate(), event.getNotes(), event.getEligibleForRehire(), event.getEmployee(), event.getAssignment(), event.getReason(), event.getType()));
    }
    
    /*
     * @param	event DeleteTerminationEvent
     */
    @EventHandler
    public void on( DeleteTerminationEvent event) {
    	Termination entity = new Termination();
   
    	// ------------------------------------------
    	// apply the TerminationId
    	// ------------------------------------------
    	entity.setTerminationId( event.getTerminationId() );
    	
    	// ------------------------------------------
    	// add to an Iterable and delete
    	// ------------------------------------------
    	entityManager.remove( entity );
    }    
    
    // attributes
	private final TerminationRepository terminationEntityRepository;
    private static final Logger LOGGER 			= Logger.getLogger(TerminationEventHandler.class.getName());

}
